import json
L = ['es', 'de', 'fr', 'tr', 'pt', 'it', 'pl', 'nl']
for i, lg in enumerate(L):
    p = f'lang/{lg}.json'; raw = open(p, encoding='utf-8').read(); d = json.loads(raw)
    add = {k: v[i] for k, v in T.items() if k not in d}
    if not add: continue
    body = raw.rstrip()[:-1].rstrip() + ',\n' + ',\n'.join(json.dumps(k, ensure_ascii=False) + ': ' + json.dumps(v, ensure_ascii=False) for k, v in add.items()) + '\n}\n'
    json.loads(body); open(p, 'w', encoding='utf-8').write(body); print(lg, len(add))
